package com.optarena.inventory.service

import com.optarena.inventory.model.Item
import com.optarena.inventory.model.Movement
import com.optarena.inventory.repository.ItemRepository
import com.optarena.inventory.repository.MovementRepository
import org.springframework.http.HttpStatus
import org.springframework.stereotype.Service
import org.springframework.web.server.ResponseStatusException

data class MovementSpec(val type: String, val quantity: Int, val note: String?)

@Service
class InventoryService(
    private val itemRepository: ItemRepository,
    private val movementRepository: MovementRepository
) {
    fun applyMovement(itemId: Long, type: String, quantity: Int, note: String?): Movement {
        val item = itemRepository.findById(itemId)
            ?: throw ResponseStatusException(HttpStatus.NOT_FOUND, "item not found")
        validate(type, quantity)
        val newQuantity = item.quantity + delta(type, quantity)
        if (newQuantity < 0) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "movement would take quantity below zero")
        }
        item.quantity = newQuantity
        itemRepository.save(item)
        return movementRepository.save(Movement(itemId = itemId, type = type, quantity = quantity, note = note))
    }

    /**
     * Applies a batch of movements atomically: validates every entry AND
     * simulates the running quantity across the whole batch first. Only
     * after the whole batch is proven safe does it actually mutate the
     * store.
     */
    fun applyBulkMovements(itemId: Long, specs: List<MovementSpec>): List<Movement> {
        val item = itemRepository.findById(itemId)
            ?: throw ResponseStatusException(HttpStatus.NOT_FOUND, "item not found")
        if (specs.isEmpty()) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "movements must be non-empty")
        }
        var simulated = item.quantity
        for (spec in specs) {
            validate(spec.type, spec.quantity)
            simulated += delta(spec.type, spec.quantity)
            if (simulated < 0) {
                throw ResponseStatusException(HttpStatus.BAD_REQUEST, "batch would take quantity below zero")
            }
        }

        return specs.map { applyMovement(itemId, it.type, it.quantity, it.note) }
    }

    private fun validate(type: String, quantity: Int) {
        if (type != "IN" && type != "OUT") {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "type must be IN or OUT")
        }
        if (quantity <= 0) {
            throw ResponseStatusException(HttpStatus.BAD_REQUEST, "quantity must be a positive integer")
        }
    }

    private fun delta(type: String, quantity: Int): Int = if (type == "IN") quantity else -quantity
}

